//! Float math for sketches, written in Fe.
//!
//! The compiler recognizes these `f32` intrinsics today:
//!
//!     __f32_from_i32   __i32_from_f32   __sqrt_f32
//!     __abs_f32        __min_f32        __max_f32   __clamp_f32
//!     __floor_f32      __ceil_f32       __trunc_f32 __round_f32
//!
//! `abs`/`min`/`max`/`clamp` graduated from hand-written Fe (`if a < b {a}
//! else {b}`, branchy WGSL) to dedicated Sonatina IR ops (`Fabs`/`Fmin`/
//! `Fmax`/`Fclamp`) mapped to a native instruction on every backend (naga
//! `abs()`/`min()`/`max()`/`clamp()`, wasm `f32.abs`/`f32.min`/`f32.max` (+
//! composed clamp), cranelift `fabs`/`fmin`/`fmax` (+ composed clamp)).
//!
//! `abs`/`min`/`max`/`clamp` are now thin wrappers over `core::num`'s
//! `Abs`/`MinMax` trait methods rather than calling the `__*_f32` externs
//! directly (float-semantics type API, slice 1:
//! `/workspace/mb2/FLOAT_SEMANTICS_TYPE_API_DESIGN.md`). This ingot stays on
//! plain `f32` throughout -- exact, pinned "WebAssembly rules" semantics on
//! every backend, unchanged -- it never imports `core::num::Regular`, the
//! relaxed single-native-instruction GPU opt-in. Same surface, same
//! semantics, same generated code; only the indirection through the trait
//! changed.
//!
//! `floor`/`ceil`/`trunc`/`round` similarly graduated to `Ffloor`/`Fceil`/
//! `Ftrunc`/`Fround`: a single native instruction on every backend (naga
//! `floor()`/`ceil()`/`trunc()`/`round()`, wasm `f32.floor`/`f32.ceil`/
//! `f32.trunc`/`f32.nearest`, cranelift `floor`/`ceil`/`trunc`/`nearest`), no
//! bit-twiddling, no NaN/-0 subtlety. `floor` used to be a hand-written
//! branch (`let t = trunc(x); if t > x { t - 1.0 } else { t }`, itself built
//! on a round-trip through `__i32_from_f32`/`__f32_from_i32`); it is now
//! branch-free, which makes `fract`/`wrap_pi`/`sin` branch-free too since
//! they build on `floor`. `round` is `roundTiesToEven` (IEEE 754): all three
//! backends agree exactly (wasm `f32.nearest`, cranelift `nearest`, and naga
//! `MathFunction::Round` -> SPIR-V `GLSL.std.450 RoundEven`), so there is no
//! divergence to pin around, unlike `min`/`max`.
//!
//! See `NUMERIC_INTRINSICS_STAGING.md` at the Fe repo root.
//!
//! `__rsqrt_f32` is still declared but deliberately unrecognized
//! (`classify.rs`, with a test pinning the set): it stays an extern "until it
//! has an explicit runtime and backend lowering". `sin`/`cos` below remain
//! ordinary Fe (a hand-chosen parabola approximation): no backend has a
//! native `sin`/`cos` instruction, so there is no intrinsic to graduate to.

use core::marker::Copy
use core::num::{Abs, FloatRounding}
use core::ops::MinMax
use algebra::Vec3 as AlgebraVec3

extern {
    fn __f32_from_i32(_: i32) -> f32
    fn __i32_from_f32(_: f32) -> i32
    fn __sqrt_f32(_: f32) -> f32
}

pub const PI: f32 = 3.14159265
pub const TAU: f32 = 6.28318531
pub const HALF_PI: f32 = 1.57079633

// ---------------------------------------------------------------------------
// The pieces the intrinsics do not give us yet
// ---------------------------------------------------------------------------

/// The two conversions, re-exported under names that read like maths rather
/// than like intrinsics.
pub fn from_i32(_ n: i32) -> f32 {
    __f32_from_i32(n)
}

/// Truncates toward zero. See `floor` for the other rounding.
pub fn to_i32(_ x: f32) -> i32 {
    __i32_from_f32(x)
}

pub fn abs(_ x: f32) -> f32 {
    x.abs()
}

pub fn min(_ a: f32, _ b: f32) -> f32 {
    a.min(b)
}

pub fn max(_ a: f32, _ b: f32) -> f32 {
    a.max(b)
}

pub fn clamp(_ x: f32, _ lo: f32, _ hi: f32) -> f32 {
    x.clamp(lo, hi)
}

pub fn clamp01(_ x: f32) -> f32 {
    clamp(x, 0.0, 1.0)
}

/// Truncate toward zero. Naming it separates "round toward zero" from
/// "round toward negative infinity", which is the distinction `floor` turns
/// on.
pub fn trunc(_ x: f32) -> f32 {
    x.trunc()
}

/// Round toward negative infinity.
pub fn floor(_ x: f32) -> f32 {
    x.floor()
}

/// Round toward positive infinity.
pub fn ceil(_ x: f32) -> f32 {
    x.ceil()
}

/// Round to the nearest integer, ties to even (IEEE 754 `roundTiesToEven`).
pub fn round(_ x: f32) -> f32 {
    x.round()
}

pub fn fract(_ x: f32) -> f32 {
    x - floor(x)
}

pub fn sqrt(_ x: f32) -> f32 {
    __sqrt_f32(x)
}

/// Linear interpolation. `t` is not clamped, so this extrapolates on purpose.
pub fn mix(_ a: f32, _ b: f32, _ t: f32) -> f32 {
    a + (b - a) * t
}

/// Hermite smoothstep between two edges.
pub fn smoothstep(_ edge0: f32, _ edge1: f32, _ x: f32) -> f32 {
    let t: f32 = clamp01((x - edge0) / (edge1 - edge0))
    t * t * (3.0 - 2.0 * t)
}

// ---------------------------------------------------------------------------
// Three-dimensional geometry
// ---------------------------------------------------------------------------

/// Small, ordinary Fe vector used by camera, ray, distance-field, and lighting
/// code. Re-exported from `algebra::Vec3<f32>` so legacy helpers and operator
/// callers share one canonical representation and evaluation order.
pub type Vec3 = AlgebraVec3<f32>

pub fn vec3(_ x: f32, _ y: f32, _ z: f32) -> Vec3 {
    AlgebraVec3 { x: x, y: y, z: z }
}

pub fn add3(_ a: Vec3, _ b: Vec3) -> Vec3 {
    a + b
}

pub fn sub3(_ a: Vec3, _ b: Vec3) -> Vec3 {
    a - b
}

pub fn scale3(_ value: Vec3, _ scale: f32) -> Vec3 {
    value * scale
}

pub fn dot3(_ a: Vec3, _ b: Vec3) -> f32 {
    a.dot(b)
}

pub fn cross3(_ a: Vec3, _ b: Vec3) -> Vec3 {
    a.cross(b)
}

pub fn length3(_ value: Vec3) -> f32 {
    value.norm()
}

pub fn normalize3(_ value: Vec3) -> Vec3 {
    scale3(value, 1.0 / max(length3(value), 0.0000001))
}

pub fn mix3(_ a: Vec3, _ b: Vec3, _ amount: f32) -> Vec3 {
    a + (b - a) * amount
}

/// A finite parameter interval along a normalized world-space ray. `active`
/// is false when the ray misses the clipping domain or the domain lies wholly
/// outside the caller's non-negative distance budget.
pub struct RayInterval { pub start: f32, pub end: f32, pub active: bool }

impl Copy for RayInterval {}

/// Intersect a normalized ray with a finite sphere and clamp the result to
/// `[0, max_distance]`. All inputs are finite and `radius`/`max_distance` are
/// non-negative domain parameters. This clips a rendering/search DOMAIN; it
/// says nothing about whether an implicit surface exists inside that domain.
/// Callers can consequently avoid marching known-empty space without
/// replacing their field evaluator with an analytic surface intersection.
pub fn unit_ray_sphere_interval(
    _ origin: Vec3,
    _ unit_direction: Vec3,
    _ center: Vec3,
    _ radius: f32,
    _ max_distance: f32,
) -> RayInterval {
    let offset: Vec3 = sub3(origin, center)
    let half_b: f32 = dot3(offset, unit_direction)
    let discriminant: f32 = half_b * half_b - (dot3(offset, offset) - radius * radius)
    // Evaluate one uniform arithmetic path across a GPU wave. For a miss the
    // absolute value keeps sqrt finite and `active` rejects the inert bounds;
    // no lane needs a discriminant branch before the expensive march.
    let root: f32 = sqrt(abs(discriminant))
    let near: f32 = -half_b - root
    let far: f32 = -half_b + root
    // Branch-free max(0, near) and min(max_distance, far), valid under the
    // finite-input contract above. This is materially smaller than lowering
    // the full IEEE min/max NaN policy into every fragment.
    let start: f32 = 0.5 * (near + abs(near))
    let end: f32 = 0.5 * (far + max_distance - abs(far - max_distance))
    RayInterval { start: start, end: end, active: discriminant >= 0.0 && end > start }
}

/// The same finite-sphere interval specialized for a camera whose origin is
/// `target - unit_forward * camera_distance`. Forward-facing camera rays and
/// the caller's finite distance/radius bounds guarantee intersections lie in
/// front of the camera. This avoids reconstructing the target offset in every
/// fragment while preserving the general interval above for arbitrary rays.
pub fn targeted_camera_sphere_interval(
    _ unit_forward: Vec3,
    _ unit_direction: Vec3,
    _ camera_distance: f32,
    _ radius: f32,
) -> RayInterval {
    let half_b: f32 = -camera_distance * dot3(unit_forward, unit_direction)
    let discriminant: f32 = half_b * half_b - (camera_distance * camera_distance - radius * radius)
    let root: f32 = sqrt(abs(discriminant))
    let near: f32 = -half_b - root
    let far: f32 = -half_b + root
    RayInterval { start: 0.5 * (near + abs(near)), end: far, active: discriminant >= 0.0 }
}

/// A world-space camera ray derived entirely in Fe.
pub struct OrbitRay { pub origin: Vec3, pub direction: Vec3 }

impl Copy for OrbitRay {}

/// Build a look-at ray from an orbit camera and normalized fragment plane.
/// Interaction policy remains outside this pure construction; any Fe actor can
/// feed it yaw/pitch/distance state from its preferred event vocabulary.
pub fn orbit_ray(
    _ yaw: f32,
    _ pitch: f32,
    _ distance: f32,
    _ u: f32,
    _ v: f32,
    _ target_y: f32,
    _ field_of_view: f32,
) -> OrbitRay {
    let cos_pitch: f32 = cos(pitch)
    let origin: Vec3 = vec3(
        sin(yaw) * cos_pitch * distance,
        sin(pitch) * distance,
        cos(yaw) * cos_pitch * distance,
    )
    let target: Vec3 = vec3(0.0, target_y, 0.0)
    let forward: Vec3 = normalize3(sub3(target, origin))
    let right: Vec3 = normalize3(cross3(forward, vec3(0.0, 1.0, 0.0)))
    let up: Vec3 = cross3(right, forward)
    let direction: Vec3 = normalize3(
        add3(
            forward,
            add3(
                scale3(right, u * field_of_view),
                scale3(up, v * field_of_view),
            ),
        ),
    )
    OrbitRay { origin: origin, direction: direction }
}

// ---------------------------------------------------------------------------
// Sampling
// ---------------------------------------------------------------------------

/// A continuous sample position inside the integer pixel `(px, py)`.
///
/// `ordered_2x2` places one sample in each quarter of every 2x2 pixel block.
/// The four offsets average to the pixel centre, but no sample sits on the
/// centre-aligned lattice that makes thin, rotated boundaries stair-step in
/// lockstep. It is deliberately ONE sample per pixel: expensive implicit
/// surfaces and deep fractals gain spatially stratified refinement without
/// multiplying their dominant orbit/ray-march loop. The construction is
/// branch-free and contains no renderer-specific quality or LoD policy.
pub struct PixelSample { pub x: f32, pub y: f32 }

/// The normalized `[-1, 1]` plane coordinate for a pixel sample, with y up.
pub struct PlaneSample { pub u: f32, pub v: f32 }

impl PixelSample {
    /// One ordered, stratified sample per pixel. Even coordinates use 3/8 and
    /// odd coordinates use 5/8, so every aligned 2x2 block contains all four
    /// subpixel quadrants and has centroid `(0.5, 0.5)`.
    pub fn ordered_2x2(_ px: i32, _ py: i32) -> Self {
        let x_parity: i32 = px & 1
        let y_parity: i32 = py & 1
        Self {
            x: from_i32(px) + 0.375 + 0.25 * from_i32(x_parity),
            y: from_i32(py) + 0.375 + 0.25 * from_i32(y_parity),
        }
    }

    /// Map this sample to the conventional square fragment plane.
    pub fn plane(self, _ resolution: f32) -> PlaneSample {
        PlaneSample { u: self.x / resolution * 2.0 - 1.0, v: 1.0 - self.y / resolution * 2.0 }
    }

    /// Map this sample to a resolution-correct rectangular fragment plane.
    /// The shorter backing-store axis retains the declared field of view, so
    /// responsive surfaces neither crop a low-resolution square nor stretch a
    /// non-square viewport. Browser code supplies only the measured extent;
    /// this Fe construction owns the projection policy.
    pub fn plane_extent(self, _ width: f32, _ height: f32) -> PlaneSample {
        let scale: f32 = max(min(width, height), 1.0)
        PlaneSample { u: (self.x * 2.0 - width) / scale, v: (height - self.y * 2.0) / scale }
    }
}

// ---------------------------------------------------------------------------
// Periodic functions
//
// There is no libm, and that is the interesting part rather than a limitation:
// a shader's `sin` is always a polynomial someone chose, so this one chooses
// out loud. The parabolic fit refined once stays within about a thousandth over
// the whole cycle, for four multiplies and no table.
// ---------------------------------------------------------------------------

/// Fold `x` into `[-PI, PI]`, the window the fit below is valid on.
pub fn wrap_pi(_ x: f32) -> f32 {
    x - TAU * floor(x / TAU + 0.5)
}

pub fn sin(_ x: f32) -> f32 {
    let t: f32 = wrap_pi(x)
    // Parabola through the zeros at -PI, 0 and PI, matched to sin at the peaks.
    let p: f32 = 1.27323954 * t - 0.40528473 * t * abs(t)
    // One refinement pass. 0.225 is the classic fit constant.
    0.225 * (p * abs(p) - p) + p
}

pub fn cos(_ x: f32) -> f32 {
    sin(x + HALF_PI)
}

// ---------------------------------------------------------------------------
// Colour
// ---------------------------------------------------------------------------

/// Pack unit-interval channels into the RGBA8 word `--mode render` returns.
/// Alpha is always opaque, and an opaque top byte is what makes this negative
/// as a signed word, which is why the constant is written the way it is.
pub fn rgba(_ r: f32, _ g: f32, _ b: f32) -> i32 {
    let ri: i32 = __i32_from_f32(clamp01(r) * 255.0)
    let gi: i32 = __i32_from_f32(clamp01(g) * 255.0)
    let bi: i32 = __i32_from_f32(clamp01(b) * 255.0)
    ri + gi * 256 + bi * 65536 + -16777216
}

pub fn grey(_ v: f32) -> i32 {
    rgba(v, v, v)
}

/// A cosine palette: a smooth loop through colour space from three phases.
/// Much less code than a gradient table, and it reads better.
pub fn palette(_ t: f32, _ phase_r: f32, _ phase_g: f32, _ phase_b: f32) -> i32 {
    rgba(
        0.5 + 0.5 * cos(TAU * (t + phase_r)),
        0.5 + 0.5 * cos(TAU * (t + phase_g)),
        0.5 + 0.5 * cos(TAU * (t + phase_b)),
    )
}

/// Shared escape-time coloring for the Mandelbrot family. The escape-radius
/// overshoot supplies a continuous fraction of one iteration, removing the
/// integer-count bands without a logarithm intrinsic or another orbit sample.
/// `magnitude_squared` is the first finite `|z|^2 > 4` value.
pub fn escape_palette(_ iterations: i32, _ magnitude_squared: f32) -> i32 {
    let smooth_iterations: f32 = from_i32(iterations) + 4.0 / magnitude_squared
    palette(smooth_iterations / 256.0, 0.0, 0.33, 0.67)
