/// Build a look-at ray from an orbit camera and normalized fragment plane.
/// Interaction policy remains outside this pure construction; any Fe actor can
/// feed it yaw/pitch/distance state from its preferred event vocabulary.
pub fn orbit_ray(
    _ yaw: f32,
    _ pitch: f32,
    _ distance: f32,
    _ u: f32,
    _ v: f32,
    _ target_y: f32,
    _ field_of_view: f32,
) -> OrbitRay {
    let cos_pitch: f32 = cos(pitch)
    let origin: Vec3 = vec3(
        sin(yaw) * cos_pitch * distance,
        sin(pitch) * distance,
        cos(yaw) * cos_pitch * distance,
    )
