/// `ordered_2x2` places one sample in each quarter of every 2x2 pixel block.
/// The four offsets average to the pixel centre, but no sample sits on the
/// centre-aligned lattice that makes thin, rotated boundaries stair-step in
/// lockstep. It is deliberately ONE sample per pixel: expensive implicit
/// surfaces and deep fractals gain spatially stratified refinement without
/// multiplying their dominant orbit/ray-march loop. The construction is
/// branch-free and contains no renderer-specific quality or LoD policy.
pub struct PixelSample { pub x: f32, pub y: f32 }

/// Fold `x` into `[-PI, PI]`, the window the fit below is valid on.
pub fn wrap_pi(_ x: f32) -> f32 {
    x - TAU * floor(x / TAU + 0.5)
}

pub fn sin(_ x: f32) -> f32 {
    let t: f32 = wrap_pi(x)
    // Parabola through the zeros at -PI, 0 and PI, matched to sin at the peaks.
    let p: f32 = 1.27323954 * t - 0.40528473 * t * abs(t)
    // One refinement pass. 0.225 is the classic fit constant.
    0.225 * (p * abs(p) - p) + p
}

pub fn cos(_ x: f32) -> f32 {
    sin(x + HALF_PI)
}

/// Pack unit-interval channels into the RGBA8 word `--mode render` returns.
/// Alpha is always opaque, and an opaque top byte is what makes this negative
/// as a signed word, which is why the constant is written the way it is.
pub fn rgba(_ r: f32, _ g: f32, _ b: f32) -> i32 {
    let ri: i32 = __i32_from_f32(clamp01(r) * 255.0)
    let gi: i32 = __i32_from_f32(clamp01(g) * 255.0)
    let bi: i32 = __i32_from_f32(clamp01(b) * 255.0)
    ri + gi * 256 + bi * 65536 + -16777216
}

pub fn grey(_ v: f32) -> i32 {
    rgba(v, v, v)
}

/// A cosine palette: a smooth loop through colour space from three phases.
/// Much less code than a gradient table, and it reads better.
pub fn palette(_ t: f32, _ phase_r: f32, _ phase_g: f32, _ phase_b: f32) -> i32 {
    rgba(
        0.5 + 0.5 * cos(TAU * (t + phase_r)),
        0.5 + 0.5 * cos(TAU * (t + phase_g)),
        0.5 + 0.5 * cos(TAU * (t + phase_b)),
    )
}

/// Shared escape-time coloring for the Mandelbrot family. The escape-radius
/// overshoot supplies a continuous fraction of one iteration, removing the
/// integer-count bands without a logarithm intrinsic or another orbit sample.
/// `magnitude_squared` is the first finite `|z|^2 > 4` value.
pub fn escape_palette(_ iterations: i32, _ magnitude_squared: f32) -> i32 {
    let smooth_iterations: f32 = from_i32(iterations) + 4.0 / magnitude_squared
    palette(smooth_iterations / 256.0, 0.0, 0.33, 0.67)
}

